  function heading(title,description,actions='',eyebrow='VANOR / BUSINESS DEVELOPMENT'){return `<div class="page-heading"><div><div class="eyebrow">${E(eyebrow)}</div><h1>${E(title)}</h1><p>${E(description)}</p></div>${actions?`<div class="row">${actions}</div>`:''}</div>`;}
  function toolbar(extra='',query=true){const segments=[...new Set((app.view==='board'?data.work.map(w=>w.segment):data.records.map(r=>(decision(r.id).segment||r.segment||VanorFit.segment(r)))).filter(Boolean))].sort();return `<div class="toolbar"><div class="segmented" aria-label="Owner filter">${['Both','Barry','Graeme','Unassigned'].map(o=>`<button class="${app.owner===o?'active':''}" data-action="owner" data-owner="${o}">${o==='Both'?'Both directors':o}</button>`).join('')}</div>${query?`<input class="search-input" id="record-search" type="search" aria-label="Search this view" placeholder="Search people, companies or projects" value="${E(app.query)}">`:''}<select id="segment-filter" class="select" aria-label="Customer segment"><option>All segments</option>${segments.map(s=>`<option ${s===app.segment?'selected':''}>${E(s)}</option>`).join('')}</select>${app.view==='board'?'':`<select id="fit-filter" class="select" aria-label="Buyer fit">${['All fit','Strong fit','Possible fit','Not a fit','Unscored','Live signal'].map(s=>`<option ${s===app.fit?'selected':''}>${s}</option>`).join('')}</select>`}${extra}</div>`;}
  function renderToday(){const ws=currentWork(),at=D.today(),asks=ws.map(w=>({w,a:D.attention(w,at)})).filter(x=>x.a&&x.w.stage!=='Watch').sort((x,y)=>Number(y.w.pinned)-Number(x.w.pinned)||x.a.rank-y.a.rank||(x.w.nextDate||'9999').localeCompare(y.w.nextDate||'9999'));const watches=ws.filter(w=>w.stage==='Watch');const watchMissing=watches.filter(w=>!w.watchDate),watchDue=watches.filter(w=>D.watchDue(w));const reviews=candidates().filter(r=>r.classification==='Known contact'&&statusFor(r)==='New'&&matchesOwner(actualOwner(r))).slice(0,5);const active=ws.filter(w=>!['Watch','Won'].includes(w.stage));const ownReview=candidates().filter(r=>statusFor(r)!=='Reviewed'&&statusFor(r)!=='Archive'&&matchesOwner(actualOwner(r))).length;
    return heading('Today','A clear next ask. A reason to act. One person accountable.',btn('Weekly review','weekly','','','brief')+btn('Start a BD session','session','','primary','arrow'),new Intl.DateTimeFormat('en-GB',{weekday:'long',day:'numeric',month:'long',timeZone:'Europe/London'}).format(new Date()).toUpperCase())+toolbar('',false)+`<div class="stats"><div class="stat"><strong>${asks.length}</strong><div class="label">Positions needing attention</div><small>${asks.filter(x=>!x.w.confirmed).length} imported positions to confirm first</small></div><div class="stat"><strong>${active.length}</strong><div class="label">Active BD positions</div><small>Watch and won are excluded</small></div><div class="stat"><strong>${watchDue.length}</strong><div class="label">Watch reviews due</div><small>${watchMissing.length} Watch records still need a date</small></div></div><div class="today-grid"><div class="stack"><section class="panel"><div class="panel-head"><h2>Your next asks</h2><span class="tiny">Ordered by recorded need, not touch count</span></div>${asks.length?asks.slice(0,7).map(({w,a},i)=>`<article class="ask-item"><span class="ask-no">${String(i+1).padStart(2,'0')}</span><div><div class="row space-between"><h3>${E(w.company)}</h3>${w.pinned?icon('pin'):''}</div><div class="meta-line">${E(w.contact||'Contact not recorded')} <span>&middot;</span> ${E(w.owner||'Unassigned')} ${stage(w.stage)}</div><div class="next-ask">${E(w.nextAsk||'No next ask has been agreed. Decide the outcome you need before contacting them.')}</div><div class="row wrap"><span class="tag ${a.rank<3?'attention':'plain'}">${E(a.label)}${a.date?' &middot; '+friendly(a.date):''}</span><span class="spacer"></span>${btn('Prepare','prepare',w.id,'small','brief')}${btn('Open','openWork',w.id,'small','arrow')}</div></div></article>`).join(''):empty('Nothing pressing in this view','Develop the next relationship deliberately, rather than manufacture a follow-up.',btn('Open Review','navReview','','primary'))}<div class="footer-row"><span class="tiny">${asks.length>7?`${asks.length-7} more positions on the board.`:'Every active position should have a next ask.'}</span><span class="spacer"></span>${btn('Open board','navBoard','','small ghost','arrow')}</div></section>${nudgePanel()}<section class="panel"><div class="panel-head"><h2>What changed</h2><span class="tiny">Actual actions recorded here</span></div>${meaningfulEvents().length?meaningfulEvents().slice(0,4).map(e=>`<div class="review-line"><span class="avatar">${initials(e.actor)}</span><div class="names"><b>${E(e.type)}</b><small>${E(byId(e.recordId).company||work(e.entityId)?.company||'Workspace')} &middot; ${niceTime(e.at)}</small></div></div>`).join(''):empty('The history starts with your first action','Record a conversation, introduction or decision. Opening a card does not count as progress.')}</section></div><div class="stack">${funnelPanel()}<section class="panel"><div class="panel-head"><h2>Watch, not forgotten</h2>${icon('watch')}</div><div class="panel-body"><p class="muted" style="font-size:12px;line-height:1.75">${watches.length} positions are being kept out of the active workload. A review date brings them back to attention, not straight into the pipeline.</p>${watchMissing.length?`<div class="notice warn section-gap">${watchMissing.length} imported Watch positions have no revisit date. Set a date once you have checked the context.</div>`:''}</div>${[...watchDue,...watchMissing].slice(0,3).map(w=>`<div class="review-line" data-action="openWork" data-id="${E(w.id)}" tabindex="0" role="button"><div class="names"><b>${E(w.company)}</b><small>${w.watchDate?'Review '+friendly(w.watchDate):'Choose a review date'}</small></div>${icon('chevron')}</div>`).join('')}<div class="footer-row">${btn('Review Watch','watchView','','small ghost','arrow')}</div></section><section class="panel"><div class="panel-head"><h2>Start with the network</h2><span class="tag plain">${ownReview.toLocaleString('en-GB')} to assess</span></div>${reviews.map(r=>`<div class="review-line" data-action="openRecord" data-id="${E(r.id)}" tabindex="0" role="button">${ownerAvatar(actualOwner(r))}<div class="names"><b>${E(r.name)}</b><small>${E(r.company)}</small></div>${icon('chevron')}</div>`).join('')||empty('No unreviewed known contacts in this view','All other source records remain available in Review and Relationships.')}<div class="footer-row"><span class="tiny">Known relationships first. Full universe retained.</span></div></section></div></div>`;
  }
  const FUNNEL_STEPS=['sent','reply','meeting_booked','meeting_held','proposal','won'],FUNNEL_LABEL={sent:'Sent',reply:'Replies',meeting_booked:'Meetings booked',meeting_held:'Meetings held',proposal:'Proposals',won:'Won'};
  function funnelStep(e){const t=String(e.type||'');if(t.startsWith('Outcome: '))return FUNNEL_STEPS.includes(t.slice(9))?t.slice(9):null;return {'Meeting held':'meeting_held','Meeting arranged':'meeting_booked','Commercial discussion':'proposal','Interaction: email out':'sent','Interaction: email in':'reply','Interaction: meeting':'meeting_held'}[t]||(t==='Interaction: note'?(n=>n.startsWith('meeting booked')?'meeting_booked':n.startsWith('proposal sent')?'proposal':n.startsWith('won:')?'won':null)(String(e.note||'').toLowerCase()):null);}
  function funnelStats(days){const since=D.addDays(D.today(),-days);const people={};FUNNEL_STEPS.forEach(s=>people[s]=new Set());const trig={};data.events.forEach(e=>{const s=funnelStep(e);if(!s)return;const d=String(e.happenedOn||e.date||e.at||'').slice(0,10);if(d<since)return;const rid=String(e.recordId||e.entityId);if(app.owner!=='Both'&&!matchesOwner(actualOwner(byId(rid))))return;people[s].add(rid);const r=byId(rid),t=e.trigger||(r.companyIntel&&r.companyIntel.signals&&r.companyIntel.signals[0]&&r.companyIntel.signals[0].type)||(r.origin==='intel'?'scan':'none');const b=trig[t]||(trig[t]={sent:new Set(),replies:new Set(),meetings:new Set()});if(s==='sent')b.sent.add(rid);if(s==='reply')b.replies.add(rid);if(s==='meeting_booked'||s==='meeting_held')b.meetings.add(rid);});const n={};FUNNEL_STEPS.forEach(s=>n[s]=people[s].size);const pct=(a,b)=>b?Math.round(100*a/b)+'%':'-';return {since,n,replyRate:pct(n.reply,n.sent),meetingRate:pct(n.meeting_booked+n.meeting_held,n.sent),byTrigger:Object.entries(trig).map(([t,b])=>({t,sent:b.sent.size,replies:b.replies.size,meetings:b.meetings.size,rate:pct(b.replies.size,b.sent.size)})).sort((a,b)=>b.sent-a.sent)};}
  function funnelPanel(){const f=funnelStats(30),steps=['sent','reply','meeting_booked','meeting_held','proposal'];const max=Math.max(1,...steps.map(s=>f.n[s]));return `<section class="panel"><div class="panel-head"><h2>Outreach funnel</h2><span class="tiny">Last 30 days &middot; reply rate ${f.replyRate} &middot; meeting rate ${f.meetingRate}</span></div><div class="panel-body"><div class="funnel">${steps.map(s=>`<div class="funnel-row"><span class="funnel-label">${FUNNEL_LABEL[s]}</span><span class="funnel-bar"><i style="width:${Math.round(100*f.n[s]/max)}%"></i></span><b>${f.n[s]}</b></div>`).join('')}</div>${f.byTrigger.length?`<table class="funnel-table"><thead><tr><th>Trigger</th><th>Sent</th><th>Replies</th><th>Meetings</th><th>Reply rate</th></tr></thead><tbody>${f.byTrigger.slice(0,6).map(x=>`<tr><td>${E(x.t.replace('_',' '))}</td><td>${x.sent}</td><td>${x.replies}</td><td>${x.meetings}</td><td>${x.rate}</td></tr>`).join('')}</tbody></table>`:`<p class="tiny">Counts what was actually sent, answered and booked (logged from Outlook each morning). Drafts do not count. Nothing recorded yet.</p>`}</div></section>`;}
  const DAYMS=864e5;const daysAgo=d=>{const t=Date.parse(d||'');return isNaN(t)?9999:(Date.now()-t)/DAYMS;};
  let wayInCache=null;
  function warmScore(r){const d=decision(r.id);let v=0;(workByRecord.get(r.id)||[]).forEach(w=>{if(!w.archived&&!['Watch'].includes(w.stage))v=Math.max(v,w.stage==='Won'?5:w.stage==='Commercial'||w.stage==='Opportunity'?4:3);});if(r.classification==='Known contact')v=Math.max(v,2);const lc=daysAgo(r.lastContact);if(lc<=90)v=Math.max(v,3);else if(lc<=365)v=Math.max(v,2);const c=d.conditions||{};if((c.Trust||0)>=1||(c.Respect||0)>=1)v=Math.max(v,3);return v;}
  /* Warm path: the warmest person we already know at the same company. */
  function wayIn(r){if(!wayInCache){wayInCache=new Map();data.records.forEach(x=>{if(x.kind==='opportunity')return;const k=globalThis.VanorPriority?globalThis.VanorPriority.norm(x.company):String(x.company||'').toLowerCase();if(!k)return;const v=warmScore(x);if(!v)return;const cur=wayInCache.get(k);if(!cur||v>cur.v)wayInCache.set(k,{v,r:x});});}
    if(warmScore(r)>=2)return null;const k=globalThis.VanorPriority?globalThis.VanorPriority.norm(r.company):String(r.company||'').toLowerCase();const hit=wayInCache.get(k);if(!hit||hit.r.id===r.id)return null;const w=(workByRecord.get(hit.r.id)||[]).find(x=>!x.archived);return {r:hit.r,why:w?('on the board: '+w.stage):hit.r.classification==='Known contact'?'known contact':daysAgo(hit.r.lastContact)<=90?'spoke in the last 90 days':'warm'};}
  function chaseList(){const sent=new Map(),answered=new Map();data.events.forEach(e=>{const st=funnelStep(e);if(!st)return;const rid=String(e.recordId||e.entityId),d=String(e.happenedOn||e.date||e.at||'').slice(0,10);if(st==='sent'){if(!sent.has(rid)||sent.get(rid)<d)sent.set(rid,d);}else if(!answered.has(rid)||answered.get(rid)<d)answered.set(rid,d);});
    const out=[];sent.forEach((d,rid)=>{const age=daysAgo(d);if(age<7||age>35)return;if((answered.get(rid)||'')>=d)return;const r=byId(rid);if(!r.name&&!r.company)return;if(!matchesOwner(actualOwner(r)))return;const x=priorities().byId.get(rid);out.push({r,days:Math.floor(age),score:x?x.p.score:0});});return out.sort((a,b)=>b.score-a.score||b.days-a.days);}
