  function addContact(){openModal({title:'Add a relationship',deck:'A person, not an automatic sales opportunity.',body:`<div class="stack" style="gap:14px">${modalField('Full name','name')}${modalField('Company','company')}${modalField('Role','jobTitle')}${modalField('Email (optional)','email','','email')}${modalField('Relationship owner','sourceOwner',app.actor,'text',['Barry','Graeme'])}${modalField('Segment','segment','')}${modalField('How do you know them?','context','','textarea')}</div>`,submit:'Add to Review',onSubmit:async f=>{const p=Object.fromEntries(f.entries());if(!p.name||!p.company)throw new Error('Enter a name and company.');const r={...p,id:'M-'+newId(),kind:'relationship',classification:'Known contact',origin:'manual',source:'Founder added',notes:'',route:'Direct sale',linkedIds:[],raw:{...p}};await repo.addSource(r);await reload();app.view='review';app.reviewTab='All';app.selected=r.id;app.owner='Both';render();toast('Added to Review. No opportunity or outreach was created.');}});}
