  async function sourceImport(file){const incoming=await readJson(file);D.seedCheck(incoming);const diff=D.importDiff(data.records,incoming);openModal({title:'Review the source import',deck:'Only source-owned fields will change.',body:`<div class="data-grid"><div><strong>${diff.added}</strong><small>New records</small></div><div><strong>${diff.changed}</strong><small>Changed source records</small></div><div><strong>${diff.missing}</strong><small>Missing upstream; retained</small></div></div><div class="notice">Your ownership decisions, buyer evidence, next asks, Watch dates, board stages and activity history will not be overwritten.</div><p class="muted section-gap" style="font-size:12px">${incoming.records.length.toLocaleString('en-GB')} rows from ${E(incoming.meta.name||file.name)}. Updated records appear under Changed after a previous review. No new opportunity is automatically qualified.</p>`,submit:'Import source only',onSubmit:async()=>{await repo.importSource(incoming);await reload();render();toast('Source updated. Founder decisions and board positions preserved.');}});}
  async function backupImport(file){const b=await readJson(file);root.VanorRepositories.validateBackup(b);openModal({title:'Restore this working backup?',deck:'This replaces this browser workspace, not SharePoint or V6.',body:`<div class="notice warn">Restore ${b.records.length} source rows, ${Object.keys(b.decisions).length} decisions, ${b.work.length} BD positions and ${b.events.length} activity events. ${repo.persistent===false?'Export the current temporary session first if you need to keep it.':'A pre-restore recovery snapshot is retained in this browser database.'}</div><p class="muted section-gap" style="font-size:12px">Exported ${E(b.exportedAt||'date not recorded')}. No email will be sent and no live system will be changed.</p>`,submit:'Restore this backup',onSubmit:async()=>{await repo.restore(b);await reload();app.drawer=null;render();toast('Full working backup restored.');}});}
  function legacy(){let previous;try{previous=JSON.parse(localStorage.getItem('vanorBdEditsV3')||'null');}catch{}if(previous&&Object.keys(previous).length){legacyPreview(Object.entries(previous).map(([id,d])=>({id,...d})));}else element.querySelector('#legacy-file')?.click();}
  function legacyPreview(raw){const rows=Array.isArray(raw)?raw:Object.entries(raw||{}).map(([id,v])=>({id,...v}));const matched=rows.filter(d=>recordMap.has(d.id)),unknown=rows.length-matched.length;openModal({title:'Import earlier review decisions',deck:'Recover prior work without presenting missing evidence as fact.',body:`<div class="notice">${matched.length} matching source records; ${unknown} unmatched entries will not be assigned by guessed name matches.</div><p class="muted section-gap" style="font-size:12px">Earlier exports did not include all evidence, Watch details or history. Scores without notes remain unconfirmed. Existing V5 decisions are not overwritten. A Watch entry with no review date is flagged for completion.</p>`,submit:'Import matching, new decisions',onSubmit:async()=>{let n=0;for(const d of matched){if(data.decisions[d.id])continue;const r=byId(d.id),conditions={};D.CONDITIONS.forEach(k=>{conditions[k]={score:Number(d.scores?.[k]||0),note:d.evidenceNotes?.[k]||'',by:'Legacy import',at:''};});const p={id:d.id,owner:D.owner(d.relationshipOwner),commercialLead:d.commercialLead||'',serviceLead:d.serviceLead||'',segment:d.segment||r.segment||VanorFit.segment(r),conditions,blocker:D.CONDITIONS.includes(d.blocker)?d.blocker:'',nextAsk:d.nextAction||'',nextDate:D.dateOnly(d.nextDate),problem:d.liveProblem||'',buyer:d.buyerRoute||'',status:d.relevance==='No'?'Archive':d.stage==='WATCH'?'Watch':d.reviewed?'Reviewed':'Unreviewed',reviewedAt:d.reviewed?new Date().toISOString():'',reviewedFingerprint:d.reviewed?D.sourceHash(r):'',watchDate:D.dateOnly(d.watchReviewDate||d.watchDate),watchReason:d.watchReason||'',note:'Imported prior decisions; verify missing evidence.'};await repo.saveDecision(p,0,{type:'Legacy decision recovered',actor:app.actor,recordId:d.id,note:'No inferred replacement for missing legacy evidence.'});n++;}await reload();render();toast(n+' prior decisions recovered.');}});}
