  function dragOver(event){const lane=event.target.closest('[data-lane]');if(lane){event.preventDefault();event.dataTransfer.dropEffect='move';element.querySelectorAll('.drag-over').forEach(e=>e.classList.remove('drag-over'));lane.classList.add('drag-over');}}
